@page "/dashboard"
@inject sv_cd8f70a892924996a0ca16d4ce43e6a3.Services.WarehouseState WarehouseState
@inject sv_cd8f70a892924996a0ca16d4ce43e6a3.Services.InventoryAlertService AlertService
@implements IAsyncDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<h4 class="text-muted">@WarehouseState.CurrentWarehouseName</h4>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 text-danger">@AlertService.LastLowStockCount</p>
                <p class="text-muted small">
                    Items below minimum levels. Refreshes every 10 seconds.
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource _cts = new();
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
            StateHasChanged();
        });
        WarehouseState.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;
    }

    protected override async Task OnInitializedAsync()
    {
        // Initial fetch
        await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);

        // Start polling
        _ = PollAsync(_cts.Token);
    }

    private async Task PollAsync(CancellationToken cancellationToken)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(cancellationToken))
            {
                await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose
        }
    }

    public async ValueTask DisposeAsync()
    {
        await _cts.CancelAsync();
        _cts.Dispose();

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

